CREATE OR REPLACE FUNCTION public.capture_registration_consents() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE f public.registration_forms; d jsonb; accepted boolean; offered jsonb; BEGIN SELECT * INTO f FROM public.registration_forms WHERE id=new.form_id FOR SHARE; new.consent_snapshot:='[]'::jsonb; FOR d IN SELECT * FROM jsonb_array_elements(f.legal_documents) LOOP BEGIN offered:=(new.answers->>('consent_document_'||(d->>'id')))::jsonb; EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'Atualize o formulário para conferir a versão dos documentos.'; END; IF offered IS NULL OR offered IS DISTINCT FROM d THEN RAISE EXCEPTION 'Os documentos foram atualizados. Recarregue e confira os novos textos antes de enviar.'; END IF; accepted:=coalesce(new.answers->>('consent_'||(d->>'id')),'')='true'; IF coalesce((d->>'required')::boolean,false) AND NOT accepted THEN RAISE EXCEPTION 'Aceite obrigatório: %',d->>'title'; END IF; new.consent_snapshot:=new.consent_snapshot||jsonb_build_array(d||jsonb_build_object('agreed',accepted,'accepted_at',new.created_at)); new.answers:=new.answers-('consent_document_'||(d->>'id')); END LOOP; new.submission_snapshot:=jsonb_build_object('full_name',new.full_name,'email',new.email,'answers',new.answers,'title',f.title,'category',f.category,'created_at',new.created_at); RETURN new; END $$;